package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class PersistentSetFactoryTest {

	@Test
	void scratchEnvironmentNeverLivesInsideDurableStore(@TempDir Path dataDirectory) throws Exception {
		Path durableMarker = Files.writeString(dataDirectory.resolve("durable-marker"), "durable");
		PersistentSetFactory<Long> factory = new PersistentSetFactory<>(dataDirectory.toFile());
		try {
			List<Path> durableChildren;
			try (var children = Files.list(dataDirectory)) {
				durableChildren = children.toList();
			}
			assertThat(durableChildren)
					.as("an abruptly terminated reader must not leave scratch LMDB environments in the store")
					.containsExactly(durableMarker);
		} finally {
			factory.close();
		}
	}
}
